def ledger_forecast_joined(
    ledger: duckdb.DuckDBPyRelation,
    forecast_group: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    if engine.row_count(forecast_group) == 0:
        return forecast_group.limit(0)
    return duckdb.sql(
        """
        SELECT account_id, group_id, week, l.units AS ledger_units,
               coalesce(g.value, 0) AS forecast_units
        FROM ledger l LEFT JOIN forecast_group g USING (account_id, group_id, week)
        WHERE group_id IS NOT NULL
        """
    )


@asset(inputs={"forecast": forecast, "ledger": ledger, "catalog": dim_item_catalog})
def forecast_reconciled(
    forecast: duckdb.DuckDBPyRelation,
    ledger: duckdb.DuckDBPyRelation,
    catalog: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    if engine.row_count(forecast) == 0:
        return engine.empty(schemas.ITEM_WEEK)
    return duckdb.sql(
        """
        WITH f AS (
            SELECT account_id, group_id, item_id, week, units::DOUBLE AS units
            FROM forecast JOIN catalog USING (item_id)
        ),
        g AS (SELECT account_id, group_id, week, sum(units) AS fu FROM f GROUP BY ALL),
        l AS (
            SELECT account_id, group_id, week, sum(units) AS lu FROM ledger
            WHERE group_id IS NOT NULL
            GROUP BY ALL
        )
        SELECT account_id, group_id, item_id, week,
               units * coalesce(lu / nullif(fu, 0), 1.0) AS value
        FROM f
        JOIN g USING (account_id, group_id, week)
        LEFT JOIN l USING (account_id, group_id, week)
        """
    )


