@asset(inputs={"ledger_prior": ledger_prior_year})
def carryover_registry(ledger_prior: duckdb.DuckDBPyRelation) -> duckdb.DuckDBPyRelation:
    external = registries.load("carryover")
    derived = duckdb.sql(
        "SELECT DISTINCT account_id, NULL::BIGINT AS item_id, week, 0.5 AS rate, "
        "'carryover' AS kind "
        "FROM ledger_prior WHERE units > 50"
    )
    if engine.row_count(external) == 0:
        return derived
    return external.union(derived)


@task(inputs={"registry": carryover_registry})
def validate_carryover_registry(registry: duckdb.DuckDBPyRelation) -> None:
    with engine.staged(registry, "registry"):
        checks.staged_matches("validate_carryover_registry", registry, "registry")
        checks.summary("validate_carryover_registry", registry)


