def carryover_account_group(
    ledger_prior: duckdb.DuckDBPyRelation,
    opt_out_registry: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    if engine.row_count(ledger_prior) == 0:
        return engine.empty(schemas.GROUP_WEEK)
    return engine.from_polars(carryover.account_group(ledger_prior.pl(), opt_out_registry.pl()))


