def validate_retirement_registry(
    registry: duckdb.DuckDBPyRelation,
    forecast_item: duckdb.DuckDBPyRelation,
) -> None:
    with engine.staged(registry, "registry") as con:
        checks.staged_matches("validate_retirement_registry", registry, "registry")
        unknown = con.sql(
            "SELECT count(*) FROM registry_rows WHERE item_id IS NOT NULL "
            "AND item_id NOT IN (SELECT item_id FROM forecast_item)"
        ).fetchall()[0][0]
    print(f"validate_retirement_registry: {unknown} registry items not in the forecast")


@asset(inputs={"registry": retirement_registry, "forecast_item": forecast_reconciled})
def driver_retirement_item(
    registry: duckdb.DuckDBPyRelation,
    forecast_item: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    if engine.row_count(registry) == 0:
        return engine.empty(schemas.ITEM_WEEK)
    with engine.staged(registry, "registry") as con:
        checks.staged_matches("driver_retirement_item", registry, "registry")
        staged = con.sql("SELECT * FROM registry_rows").pl()
    out = drivers.from_registry(staged, forecast_item.pl(), -1.0)
    return engine.from_polars(out)


