def plan_drivers_long_item(
    rollout: duckdb.DuckDBPyRelation,
    launch: duckdb.DuckDBPyRelation,
    displacement: duckdb.DuckDBPyRelation,
    retirement: duckdb.DuckDBPyRelation,
    carryover: duckdb.DuckDBPyRelation,
    campaign: duckdb.DuckDBPyRelation,
    channel: duckdb.DuckDBPyRelation,
    trend: duckdb.DuckDBPyRelation,
    account_exit: duckdb.DuckDBPyRelation,
    floor_patch: duckdb.DuckDBPyRelation,
    exited: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    return duckdb.sql(
        """
        SELECT * FROM (
            SELECT account_id, group_id, item_id, week, value,
                   'rollout' AS driver
            FROM rollout
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'launch' AS driver
            FROM launch
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'displacement' AS driver
            FROM displacement
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'retirement' AS driver
            FROM retirement
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'carryover' AS driver
            FROM carryover
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'campaign' AS driver
            FROM campaign
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'channel' AS driver
            FROM channel
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'trend' AS driver
            FROM trend
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'account_exit' AS driver
            FROM account_exit
            UNION ALL
            SELECT account_id, group_id, item_id, week, value,
                   'floor_patch' AS driver
            FROM floor_patch
        )
        WHERE account_id NOT IN (SELECT account_id FROM exited) OR driver = 'account_exit'
        """
    )


