def plan_drivers_monetized_item(
    drivers_long: duckdb.DuckDBPyRelation,
    conversion: duckdb.DuckDBPyRelation,
    launch_rate_override_week: duckdb.DuckDBPyRelation,
    rollout_rate_override_group_week: duckdb.DuckDBPyRelation,
    forecast_item: duckdb.DuckDBPyRelation,
) -> duckdb.DuckDBPyRelation:
    if engine.row_count(conversion) == 0:
        return conversion.limit(0)
    return duckdb.sql(
        """
        SELECT l.*, l.value * coalesce(lo.factor, ro.factor, c.factor, 1.0) AS amount
        FROM drivers_long l
        LEFT JOIN conversion c USING (item_id, week)
        LEFT JOIN launch_rate_override_week lo USING (item_id, week)
        LEFT JOIN rollout_rate_override_group_week ro USING (group_id, week)
        WHERE l.item_id IN (SELECT item_id FROM forecast_item)
        """
    )


