def summarize_qa(**frames: pd.DataFrame) -> None:
    for check, frame in sorted(frames.items()):
        print(f"{check}: {len(frame)} rows")
    if len(frames) != 14:
        raise ValueError(f"expected 14 QA frames, got {len(frames)}")
